// Package crd keeps the DispatchOps CRD at the operator's version. Helm
// installs the CRD from the chart's crds/ directory but never upgrades it,
// so the operator applies the one it was built with at startup.
package crd

import (
	"context"
	_ "embed"
	"fmt"
	"strings"

	"golang.org/x/mod/semver"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
	"k8s.io/apimachinery/pkg/types"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/yaml"
)

// The DispatchOps CRD, generated by `make manifests` (which copies it to
// the chart's crds/).
//
//go:embed dispatch-ops.io_dispatchops.yaml
var manifest []byte

// Name is the DispatchOps CRD's name.
const Name = "dispatchops.dispatch-ops.io"

// VersionAnnotation records on the CRD the version of the operator that
// last applied it.
const VersionAnnotation = "dispatch-ops.io/operator-version"

// FieldOwner is the field manager the operator applies the CRD as.
const FieldOwner = "dispatch-ops-operator"

// Ensure applies the embedded CRD unless an operator newer than version
// applied it already, so a rollback or an older replica in a rolling
// update never takes it back. The CRD must exist: the operator may only
// get and patch it, not create it. A version that isn't semver (a
// development build) always applies.
func Ensure(ctx context.Context, c client.Client, version string) error {
	current := &unstructured.Unstructured{}
	current.SetAPIVersion("apiextensions.k8s.io/v1")
	current.SetKind("CustomResourceDefinition")
	if err := c.Get(ctx, types.NamespacedName{Name: Name}, current); err != nil {
		if apierrors.IsNotFound(err) {
			return fmt.Errorf("the %s CRD is not installed: install the chart without --skip-crds, "+
				"or apply its crds/ directory", Name)
		}
		return fmt.Errorf("getting the %s CRD: %w", Name, err)
	}
	if newer(current.GetAnnotations()[VersionAnnotation], version) {
		return nil
	}
	want, err := Manifest()
	if err != nil {
		return err
	}
	annotations := want.GetAnnotations()
	if annotations == nil {
		annotations = map[string]string{}
	}
	annotations[VersionAnnotation] = version
	want.SetAnnotations(annotations)
	if err := c.Patch(ctx, want, client.Apply, client.FieldOwner(FieldOwner), client.ForceOwnership); err != nil {
		return fmt.Errorf("applying the %s CRD: %w", Name, err)
	}
	return nil
}

// Manifest returns the embedded CRD.
func Manifest() (*unstructured.Unstructured, error) {
	obj := map[string]any{}
	if err := yaml.Unmarshal(manifest, &obj); err != nil {
		return nil, fmt.Errorf("parsing the embedded %s CRD: %w", Name, err)
	}
	return &unstructured.Unstructured{Object: obj}, nil
}

// newer reports whether applied, the version that last applied the CRD,
// is a release newer than version. Only releases are compared: a
// development build neither yields to nor holds back another.
func newer(applied, version string) bool {
	a, v := canonical(applied), canonical(version)
	if a == "" || v == "" {
		return false
	}
	return semver.Compare(a, v) > 0
}

// canonical returns version as a valid semver with a leading v, or "".
func canonical(version string) string {
	if version == "" {
		return ""
	}
	if !strings.HasPrefix(version, "v") {
		version = "v" + version
	}
	if !semver.IsValid(version) {
		return ""
	}
	return version
}
